moved=False
def states():
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=7).stdout.strip() for n in ("ssh","nginx","pink-vpn","pink-iptv-backend","pm2-root","pm2-iptvpn-bot","lowcost-europa","fadego-staging")}
try:
 if not root.is_dir() or root.is_symlink() or not (root/"vpn").is_dir():raise RuntimeError("project_root_invalid")
