 st=src.stat()
 if st.st_dev!=dst.parent.stat().st_dev or st.st_uid!=0 or st.st_gid!=0 or st.st_mode&0o777!=0o700:raise RuntimeError("filesystem_or_owner_mode_invalid")
 entries=sorted(src.iterdir())
 if len(entries)!=5 or len([f for f in entries if f.name.startswith("pink_vpn_052_") and f.suffix==".py"])!=4:raise RuntimeError("unexpected_original_directory_layout")
 if any(not f.is_file() or f.is_symlink() for f in entries):raise RuntimeError("not_regular_files")
 hashes={f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in entries}
