 baseline=states()
 if baseline["pink-vpn"]!="active":raise RuntimeError("active_vpn_not_running")
 os.rename(src,dst);moved=True
 os.symlink(str(dst),src)
 after=dst.stat()
 if (after.st_dev,after.st_ino,after.st_uid,after.st_gid,after.st_mode&0o777)!=(st.st_dev,st.st_ino,st.st_uid,st.st_gid,st.st_mode&0o777):raise RuntimeError("source_directory_identity_drift")
 if not src.is_symlink() or src.resolve(strict=True)!=dst or any(hashlib.sha256((dst/f).read_bytes()).hexdigest()!=h for f,h in hashes.items()):raise RuntimeError("file_hash_or_alias_postcheck_failed")
 if subprocess.run(["systemd-analyze","verify",str(unit)],capture_output=True,timeout=12).returncode!=0:raise RuntimeError("vpn_unit_invalid")
 if states()!=baseline:raise RuntimeError("services_changed")
 out.update(status="MOVED_VERIFIED",changed=True,physical_root=str(dst),legacy_alias=str(src),original_file_count=len(entries),original_files_hash_verified=True,root_mode_preserved=True,service_states_unchanged=True,active_vpn_not_restarted=True)
